from pathlib import Path
import sys,json,numpy as np
from scipy.linalg import cho_factor,cho_solve
from scipy.sparse import csr_matrix
from scipy.sparse.linalg import LinearOperator,gmres
p=Path(__file__).resolve().parent;sys.path.insert(0,str(p.parent/'rain-corrected-coupled-reference'));from setup import m,r
ownership=json.loads((p.parent/'rain-articulation-factorization/result.json').read_text())
factors=[(np.array(g['free_rows']),cho_factor(r.Hff[np.ix_(g['free_rows'],g['free_rows'])],lower=True)) for g in ownership['groups']]
def H(x):return m.J@(m.M@(m.J.T@x))+m.G@x
def Schur(v):
 x=np.zeros(m.offset);x[r.remaining]=v;g=H(x);rhs=-g[r.free]
 for ii,f in factors:x[r.free[ii]]=cho_solve(f,rhs[ii])
 return H(x)[r.remaining]
rng=np.random.default_rng(20261007);errors=[]
for i in range(24):
 v=rng.normal(size=r.N);want=r.S@v;errors.append(float(max(abs(Schur(v)-want)/(1+abs(want)))))
assert max(errors)<=1e-9
pre_groups={}
for b,o in zip(r.blocks,ownership['remaining_ownership']):
 assert b['original']['label']==o['label'];pre_groups.setdefault(tuple(o['owners']),[]).extend(b['indices'])
def jac_action(y,lam):
 grad=r.S@y+r.q;P=np.zeros((r.N,r.N));C=np.zeros_like(P);steps=np.zeros(r.N)
 for b in r.blocks:
  ii=b['indices'];n=len(ii);z=y[ii]-b['step']*grad[ii];domain=b['original']['domain'];Dz=np.eye(n);Dc=np.zeros(n)
  if domain=='positive':Dz=np.diag((z>0).astype(float))
  elif domain=='box':
   cap=r.radius(b,y);Dz=np.diag((abs(z)<cap).astype(float));Dc=np.where(abs(z)>=cap,np.sign(z),0)
  elif domain=='ball':
   cap=r.radius(b,y);length=np.linalg.norm(z)
   if length>cap:u=z/length;Dz=cap/length*(np.eye(n)-np.outer(u,u));Dc=u
  P[np.ix_(ii,ii)]=Dz;steps[ii]=b['step']
  if b['normal_indices'] is not None and r.radius(b,y)>0:C[np.ix_(ii,b['normal_indices'])]=np.outer(Dc,b['original']['weights'])
 P=csr_matrix(P);C=csr_matrix(C)
 return lambda v:(1+lam)*v-P@(v-steps*Schur(v))-C@v
records=[]
def audit(y,lam,F,D):
 action=jac_action(y,lam);v=rng.normal(size=r.N);want=D@v;control=float(max(abs(action(v)-want)/(1+abs(want))));assert control<=1e-9
 local=[(np.array(ii),np.linalg.pinv(D[np.ix_(ii,ii)],rcond=1e-12)) for ii in pre_groups.values()]
 def pre(v):
  out=np.zeros_like(v)
  for ii,inv in local:out[ii]=inv@v[ii]
  return out
 count=0;last=None
 def mv(v):
  nonlocal count
  count+=1
  if count>160:raise RuntimeError('action-cap')
  return action(v)
 try:
  x,info=gmres(LinearOperator((r.N,r.N),matvec=mv,dtype=float),-F,M=LinearOperator((r.N,r.N),matvec=pre,dtype=float),restart=32,maxiter=4,rtol=1e-6,atol=1e-12)
  residual=float(np.linalg.norm(action(x)+F));relative=residual/max(np.linalg.norm(F),1e-300);passed=residual<=max(1e-12,1e-6*np.linalg.norm(F))
 except RuntimeError:
  info='action-cap';relative=None;residual=None;passed=False
 records.append(dict(lam=lam,actions=count,info=info,relative_residual=relative,absolute_residual=residual,pass_screen=bool(passed),jacobian_control=control));print('KRYLOV',records[-1],flush=True)
source=(p.parent/'rain-projected-continuation/run.py').read_text()
source=source.replace("for name,seed in [('cold',np.zeros(r.N)),('capped',m.old[r.remaining].copy())]:","for name,seed in [('capped',m.old[r.remaining].copy())]:")
source=source.replace('D=r.residual(y,True)+lam*r.E;delta,','D=r.residual(y,True)+lam*r.E;audit(y,lam,F,D);delta,')
exec(compile(source,str(p/'replay.py'),'exec'))
result=dict(status='all-systems-pass' if all(v['pass_screen'] for v in records) else 'linear-budget-failed',schur_control=max(errors),preconditioner_sizes=[len(v) for v in pre_groups.values()],systems=len(records),failed=sum(not v['pass_screen'] for v in records),records=records)
(p/'linear-audit.json').write_text(json.dumps(result,indent=2));print('SUMMARY',json.dumps({k:v for k,v in result.items() if k!='records'}),flush=True)
